cd apps/client && cat >> src/lib/research/screen.ts <<'EOF'

export interface ScreenCurve {
	t: number[];
	rule: (number | null)[];
	hold: (number | null)[];
}

export interface ScreenRuleTile {
	id: string;
	group: "entry" | "fill" | "exit";
	name: string;
	label: string;
	tip: string;
}

/** A trial at `h`, falling back to the feature's lead trial when that horizon was not run. */
export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
	if (h !== "lead") {
		const match = f.trials.find((t) => t.h === h);
		if (match) return match;
	}
	return f.trials.find((t) => t.h === f.lead_h) ?? f.trials[0];
}

/** Round tick values covering [lo, hi] at about five intervals, with zero kept in view. */
export function niceTicks(lo: number, hi: number): number[] {
	if (!Number.isFinite(lo) || !Number.isFinite(hi)) return [];
	if (lo > hi) [lo, hi] = [hi, lo];
	lo = Math.min(lo, 0);
	hi = Math.max(hi, 0);
	if (lo === hi) return [lo];
	const rough = (hi - lo) / 5;
	const magnitude = 10 ** Math.floor(Math.log10(rough));
	const normal = rough / magnitude;
	const step = (normal <= 1.5 ? 1 : normal <= 3 ? 2 : normal <= 7 ? 5 : 10) * magnitude;
	const start = Math.ceil(lo / step - 1e-9);
	const end = Math.floor(hi / step + 1e-9);
	const round = (v: number) => Math.round(v * 1e12) / 1e12;
	const ticks: number[] = [];
	for (let i = start; i <= end; i++) ticks.push(round(i * step));
	return ticks;
}

/** ISO calendar date with dots, so "01" can never be mistaken for a month tick. */
export function dateLabel(ms: number): string {
	const d = new Date(ms);
	const pad = (n: number) => String(n).padStart(2, "0");
	return `${d.getUTCFullYear()}.${pad(d.getUTCMonth() + 1)}.${pad(d.getUTCDate())}`;
}

/**
 * A screen's cumulative rule/hold curves as percentages. A missing point carries the previous
 * value forward (the curve is a running sum, so a gap is not a new zero).
 */
export function curveView(trial: ScreenTrial | undefined | null): {
	rule: number[];
	hold: number[];
	ticks: number[];
	labels: string[];
} | null {
	const curve = trial?.curve;
	if (!curve || !curve.t || curve.t.length < 2) return null;
	const carry = (values: (number | null)[] | undefined) => {
		let last = 0;
		return curve.t.map((_, i) => {
			const v = values?.[i];
			if (v != null && Number.isFinite(v)) last = v;
			return last * 100;
		});
	};
	const rule = carry(curve.rule);
	const hold = carry(curve.hold);
	const points = [...rule, ...hold].filter((v) => Number.isFinite(v));
	const ticks = niceTicks(Math.min(...points), Math.max(...points));
	return { rule, hold, ticks, labels: curve.t.map(dateLabel) };
}

/** Plain-language tiles for the trading rule the screen confirms. */
export function screenRule(doc: ScreenDoc, f: ScreenFeature, trial: ScreenTrial): ScreenRuleTile[] {
	const sign = doc.fixed_sign ?? trial.train_sign ?? 1;
	const up = sign >= 0;
	const foldSigns = trial.folds.map((x) => x.train_sign).filter((x) => x != null);
	const changed = new Set(foldSigns).size > 1;
	const directionLabel = changed ? "부호 바뀜" : up ? "순방향" : "역추세";
	const directionTip =
		doc.fixed_sign != null
			? `문서가 부호를 ${doc.fixed_sign > 0 ? "+" : ""}${doc.fixed_sign}로 고정했다. 지표가 0보다 크면 ${up ? "롱" : "숏"}이다.`
			: changed
				? `학습 구간마다 부호가 바뀌었다(${foldSigns.map((s) => (s > 0 ? "+" : "−")).join(" → ")}). 지표가 0보다 크면 ${up ? "롱" : "숏"}으로 본다.`
				: `학습 구간 부호 ${sign > 0 ? "+1" : "−1"}을 따른다. 지표가 0보다 크면 ${up ? "롱" : "숏"}이다.`;
	const tiles: ScreenRuleTile[] = [
		{
			id: "direction",
			group: "entry",
			name: up ? "기준 위면 롱" : "기준 위면 숏",
			label: directionLabel,
			tip: directionTip,
		},
		{
			id: "indicator",
			group: "entry",
			name: featureName(f),
			label: f.tradeable === false ? "참고 지표" : "거래 가능",
			tip: featureDef(f) || "화면의 순위 IC를 만든 지표다.",
		},
	];
	if (doc.regime === "down") {
		tiles.push({
			id: "regime",
			group: "entry",
			name: "200일선 아래만",
			label: "하락장 한정",
			tip: "종가가 200일 이동평균 아래인 날만 점수를 매기고 매매한다.",
		});
	}
	tiles.push(
		{
			id: "fill",
			group: "fill",
			name: `편도 ${(doc.cost_per_side * 1e4).toFixed(0)}bp`,
			label: "보수적 2배",
			tip: `편도 ${(doc.cost_per_side * 1e4).toFixed(0)}bp를 왕복 두 번으로 잡고 실제 펀딩도 뺀다.`,
		},
		{
			id: "hold",
			group: "exit",
			name: `${trial.h}${doc.unit} 보유`,
			label: "다음 봉 종가",
			tip: `진입 뒤 ${trial.h}${doc.unit === "H" ? "시간" : "일"}가 지난 봉의 종가에 청산한다.`,
		},
	);
	return tiles;
}
EOF
